import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Count the number of ordered pairs (x, y) of positive integers satisfying x ≤ {p} y ≤ {m_max} and y ≤ {q} x ≤ {n_max}, with gcd(x, y) = {g}. Give your answer as an integer.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose parameters to create a non-trivial wedge and sizable coprime counting task.
# We construct m_max and n_max to induce specific Umax = floor(n_max/(q*g)) and Vmax = floor(m_max/(p*g)).
# We target Umax, Vmax in [180, 600] to ensure difficulty while keeping verification tractable.
while True:
    p = rng.randint(2, 6)
    q = rng.randint(2, 6)
    g = rng.randint(1, 6)
    U_target = rng.randint(200, 600)
    V_target = rng.randint(200, 600)
    # Build m_max and n_max so that floor divisions yield the targets.
    # Any value in [p*g*V_target, p*g*V_target + p*g - 1] works to keep Vmax = V_target.
    # Similarly for U_target.
    m_base = p * g * V_target
    n_base = q * g * U_target
    m_max = m_base + rng.randint(0, max(0, p * g - 1))
    n_max = n_base + rng.randint(0, max(0, q * g - 1))
    # Sanity checks to avoid trivial domains
    Umax = n_max // (q * g)
    Vmax = m_max // (p * g)
    if Umax >= 180 and Vmax >= 180 and Umax <= 100000 and Vmax <= 100000:
        # Also avoid overly small wedge thickness: ensure q*Umax and p*Vmax are not too tiny relative.
        # Rough area proxy for wedge intersection with rectangle:
        # Approximate total v-range per u is min(q*u, Vmax) - ceil(u/p) + 1 when positive.
        approx_pairs = 0
        for u in range(1, Umax + 1):
            L = (u + p - 1) // p
            R = min(Vmax, q * u)
            if R >= L:
                approx_pairs += (R - L + 1)
        # Expect ~ 6/pi^2 fraction coprime => ~0.6079 multiplier
        approx_coprime = int(0.6079271018540267 * approx_pairs)
        if approx_coprime >= 5000:
            return {'p': p, 'q': q, 'm_max': m_max, 'n_max': n_max, 'g': g}
# Fallback (should not reach)
return {'p': 2, 'q': 2, 'm_max': 1200, 'n_max': 1200, 'g': 1}

    def verifier(assign):
# Validate and compute the exact count using Möbius inversion over divisors of u.
# The constraints are: x ≤ p*y ≤ m_max, y ≤ q*x ≤ n_max, gcd(x,y)=g.
# Substitute x=g*u, y=g*v to reduce to coprime u,v with u ≤ p*v, v ≤ q*u, v ≤ floor(m_max/(p*g)), u ≤ floor(n_max/(q*g)).
try:
    p = int(assign['p'])
    q = int(assign['q'])
    m_max = int(assign['m_max'])
    n_max = int(assign['n_max'])
    g = int(assign['g'])
except Exception:
    # Missing or non-integer parameters
    return (False, None)
# Basic domain checks
if not (p >= 2 and q >= 2 and m_max >= 1 and n_max >= 1 and g >= 1):
    return (False, None)
# Compute effective bounds for u and v after factoring out g
Umax = n_max // (q * g)
Vmax = m_max // (p * g)
if Umax <= 0 or Vmax <= 0:
    # Empty domain
    return (False, None)
# Enforce difficulty: avoid trivial small domains and extremely large ones.
if Umax < 150 or Vmax < 150:
    return (False, None)
if Umax > 100000 or Vmax > 100000:
    return (False, None)
# Prepare Möbius function mu[1..Umax] and smallest prime factor spf via linear sieve
n = Umax
mu = [0] * (n + 1)
spf = [0] * (n + 1)
mu[1] = 1
primes = []
for i in range(2, n + 1):
    if spf[i] == 0:
        spf[i] = i
        primes.append(i)
        mu[i] = -1
    for p0 in primes:
        v = p0 * i
        if v > n:
            break
        spf[v] = p0
        if i % p0 == 0:
            mu[v] = 0
            break
        else:
            mu[v] = -mu[i]
# Helper to enumerate divisors of u using spf
def divisors_of(u):
    fac = []
    x = u
    while x > 1:
        pr = spf[x]
        cnt = 0
        while x % pr == 0:
            x //= pr
            cnt += 1
        fac.append((pr, cnt))
    # Generate all divisors from prime power decomposition
    ds = [1]
    for pr, cnt in fac:
        cur = []
        mul = 1
        for _ in range(cnt):
            mul *= pr
            for d in ds:
                cur.append(d * mul)
        ds += cur
    return ds
# Count coprime v in interval for each u by Möbius over divisors of u
total = 0
for u in range(1, Umax + 1):
    L = (u + p - 1) // p  # ceil(u/p)
    if L < 1:
        L = 1
    R = Vmax
    q_u = q * u
    if q_u < R:
        R = q_u
    if R < L:
        continue
    # Sum mu[d] * (floor(R/d) - floor((L-1)/d)) over d | u
    s = 0
    for d in divisors_of(u):
        md = mu[d]
        if md == 0:
            continue
        s += md * (R // d - ((L - 1) // d))
    total += s
answer = total
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

